// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, uint256 initialBalance) public {
        vm.assume(initialBalance >= _value);
        vm.assume(initialBalance > 0);
        vm.assume(_value > 0);
        vm.deal(address(c), initialBalance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", _value));
        if (!ok) {
            return;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore - balanceAfter >= _value);
    }
}
